#!/usr/bin/env node
// SPDX-License-Identifier: Apache-2.0
// Writes libs/io-ifc/src/schema_tables.inc from cc-ifc 0.5's schema tables (lib/ifc/schema-ifc2x3.js, schema-ifc4.js,
// schema-ifc4x3.js in the frozen copy, FORK_PARITY_JS): the same rows in the same order (schema.js builds the subtype
// lists in that order), as C++ constants. The rows are data generated by cc-ifc's gen-schema.mjs from the EXPRESS
// schemas published by buildingSMART International Limited; their attribution is kept in the output.
//   FORK_PARITY_JS=<js-0.5> node tools/gen/ifc-schema.mjs
import { writeFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const js = process.env.FORK_PARITY_JS;
if (!js) { console.error('set FORK_PARITY_JS to the frozen js-0.5 copy'); process.exit(2); }
const here = dirname(fileURLToPath(import.meta.url));
const out = join(here, '../../libs/io-ifc/src/schema_tables.inc');

const q = (s) => {
  if (!/^[\x20-\x7e]*$/.test(s)) throw new Error('non-ASCII text in a schema table: ' + s);
  return '"' + s.replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"';
};

let text = `// SPDX-License-Identifier: Apache-2.0
// Generated by tools/gen/ifc-schema.mjs from cc-ifc 0.5's schema tables (lib/ifc/schema-*.js, frozen copy js-0.5): do not edit.
// The tables were generated by cc-ifc's gen-schema.mjs from the EXPRESS schemas published by buildingSMART International
// Limited (IFC2X3_TC1.exp, IFC4_ADD2_TC1.exp, IFC4X3_ADD2.exp; (c) 1996-2020 buildingSMART International Limited; used in
// software development with attribution, as its license allows). See NOTICE.
//
// ent: upper name, Name, SUPERTYPE, abstract, "attr|code;..." (own explicit attributes, file order), "derived;..."
// typ: upper name, Name, code, "select members;..." | "enum values;..." | ""
// clang-format off
`;
for (const [key, file] of [['Ifc2x3', 'schema-ifc2x3.js'], ['Ifc4', 'schema-ifc4.js'], ['Ifc4x3', 'schema-ifc4x3.js']]) {
  const t = (await import(pathToFileURL(join(js, 'lib/ifc', file)).href)).default;
  const ents = Object.entries(t.ent);
  const typs = Object.entries(t.typ);
  text += `\ninline constexpr std::string_view k${key}Source = ${q(t.source)};\n`;
  text += `inline constexpr auto k${key}Ent = std::to_array<EntRow>({\n`;
  for (const [up, e] of ents) text += `  {${q(up)}, ${q(e[0])}, ${q(e[1] || '')}, ${e[2] ? 'true' : 'false'}, ${q(e[3] || '')}, ${q(e[4] || '')}},\n`;
  text += '});\n';
  text += `inline constexpr auto k${key}Typ = std::to_array<TypRow>({\n`;
  for (const [up, y] of typs) text += `  {${q(up)}, ${q(y[0])}, ${q(y[1])}, ${q(y[2] || '')}},\n`;
  text += '});\n';
}
text += '// clang-format on\n';
writeFileSync(out, text);
console.log(`wrote ${out} (${text.length} bytes)`);
